contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address targetContract, address asset) public {
        require(targetContract != address(0));
        require(asset != address(0));

        c.configureFlashGovernance(asset, 1, 1, false);
        c.assertGovernanceApproved(address(this), targetContract, true);

        uint256 beforeBal = IERC20(asset).balanceOf(address(this));

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(IERC20(asset).balanceOf(address(this)) >= beforeBal + 1);
        } else {
            assert(reverted);
        }
    }
}

