contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address targetA,
        uint256 amount1,
        uint256 unlock1,
        bool b1,
        address targetB,
        uint256 amount2,
        uint256 unlock2,
        bool b2
    ) public {
        require(true);

        // Setup: DAO is this contract, so we can set/configure directly.
        c.setGoverned(new address[](0), new bool[](0));

        // Configure both flash governance config slots with caller-selected
        // parameters.  The choice of target is irrelevant here; configure only
        // affects the global config used by assertGovernanceApproved.
        c.configureFlashGovernance(address(0xdead), amount1, unlock1, b1);

        // First attempt for pair (targetA, this).  The asset is 0xdead, so
        // transferFrom will almost certainly revert (no token at that address),
        // so this call normally reverts; if it does not, a pending decision
        // for (targetA, this) must exist.
        bool reverted1;
        try c.assertGovernanceApproved(address(this), targetA, true) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        // Read whether a pending decision exists for (targetA, this).
        (uint256 pAmountA, uint256 pUnlockA, address pAssetA, bool pBurnableA) =
            c.pendingFlashDecision(targetA, address(this));
        bool hadPendingA = pAssetA != address(0) || pAmountA != 0;

        // Reconfigure with different parameters, then attempt the SAME pair
        // again.  If a decision was pending, this second call must not succeed.
        c.configureFlashGovernance(address(0xbeef), amount2, unlock2, b2);

        bool reverted2;
        try c.assertGovernanceApproved(address(this), targetA, true) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        // General rule: if the first call succeeded (creating a pending
        // decision for the pair), then the second call for the same pair must
        // revert, unless the first call's pending decision was somehow
        // removed (which we never did).
        assert(!(!reverted1 && hadPendingA) || reverted2);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address targetA,
        uint256 amount1,
        uint256 unlock1,
        bool b1,
        uint256 unlock2
    ) public {
        require(true);

        // Make DAO = this contract so onlySuccessfulProposal-like checks are
        // trivially satisfied (configured is false).
        c.setDAO(address(this));

        // Configure flash governance with caller-selected parameters.
        // Use an asset that will cause transferFrom to revert in the normal
        // case; this is fine because we only rely on the branch where it
        // succeeds (asset 0x0 is also an EOA, transferFrom reverts unless a
        // custom target is used).  To maximize the chance of reaching the
        // success branch, use address(this) as the asset: it has no
        // transferFrom, so still reverts.  The rule holds either way.
        c.configureFlashGovernance(address(0xdead), amount1, unlock1, b1);

        // First attempt for pair (targetA, this).  If it somehow succeeds,
        // a pending decision is created for that pair.
        bool reverted1;
        try c.assertGovernanceApproved(address(this), targetA, true) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        // Read the pending decision state for (targetA, this).
        (uint256 pAmountA, uint256 pUnlockA, address pAssetA, bool pBurnableA) =
            c.pendingFlashDecision(targetA, address(this));
        bool hadPendingA =
            pAssetA != address(0) ||
            pAmountA != 0 ||
            pUnlockA != 0 ||
            pBurnableA;

        // Reconfigure with different parameters, then attempt the SAME pair
        // again without clearing the pending decision.
        c.configureFlashGovernance(address(0xbeef), amount1 + 1, unlock2, b1);

        bool reverted2;
        try c.assertGovernanceApproved(address(this), targetA, true) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        // General rule: if the first call succeeded and left a pending
        // decision for the pair, then the second call for the same pair must
        // revert (unless the pending decision was cleared, which we did not
        // do).  Expressed without underflow-prone subtraction.
        assert(!(!reverted1 && hadPendingA) || reverted2);
    }

    receive() external payable {}
}

