contract InvMutTest {
    C c;

    event flashDecision(address actor, address deposit_asset, uint256 amount, address target);

    constructor(C _c) {
        c = _c;
    }

    function run(address dao, address asset, uint256 amount, uint256 unlockTime, address target, bool emergency) public payable {
        // We act as the DAO so that assertGovernanceApproved is callable via the c.flashEnabled() modifier.
        c.setDAO(address(this));

        // We need a real ERC20 at `asset` that will let this test contract transferFrom itself.
        // Deploying arbitrary contracts is not allowed, so instead we use the contract itself as the asset.
        // But c's own balance of the governance asset is only observable indirectly through the transferFrom return value.
        // The only safe precondition we can enforce is that amount is positive and unlockTime is non-zero.
        require(amount > 0);
        require(unlockTime > 0);

        // Configure flash governance. This requires that we are the DAO, which we just set.
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // Act as the DAO to satisfy the flashEnabled() modifier on assertGovernanceApproved.
        // No revert is allowed here because the governance asset is not necessarily transferable.
        // We therefore use try/catch around the deciding call.
        bool reverted;
        try c.assertGovernanceApproved(target, msg.sender, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: either the call reverted, or a pending flash decision for (target, msg.sender)
        // was recorded with the configured asset, amount and a non-zero unlock time, and address(c).balance
        // did not decrease (since no Ether is involved).
        FlashGovernanceConfig memory cfg = c.flashGovernanceConfig();
        (address pendingAsset, uint256 pendingAmount, uint256 pendingUnlockTime) = c.pendingFlashDecision(target, msg.sender);

        assert(
            reverted ||
            (
                cfg.asset == asset &&
                cfg.amount == amount &&
                pendingAsset == asset &&
                pendingAmount == amount &&
                pendingUnlockTime >= block.timestamp
            )
        );
    }

    receive() external payable {}
}

