contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address dao,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        uint8 maxGovernanceChangePerEpoch,
        uint256 epochSize,
        uint8 changeTolerance,
        address target,
        address sender,
        bool emergency
    ) public {
        // Ensure the contract under test points at a known DAO and that the
        // caller is allowed to configure it.  This is a precondition on the
        // parameters, not on c's state.
        require(dao != address(0), "dao");
        require(asset != address(0), "asset");
        require(target != address(0), "target");
        require(sender != address(0), "sender");

        c.setDAO(dao);

        // Configure the flash governance parameters that define the expected
        // state after a successful decision.  These calls must succeed because
        // `configured` is still false: assertSuccessfulProposal returns without
        // checking DAO.successfulProposal when !configured.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);
        c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance);

        // Read the configured values back through public getters.
        uint256 configAmount;
        uint256 configUnlockTime;
        address configAsset;
        bool configAssetBurnable;
        (configAmount, configUnlockTime, configAsset, configAssetBurnable) = c.flashGovernanceConfig();

        // Record the timestamp at which the deciding call will execute.  The
        // rule below is derived from this timestamp, so the test is valid for
        // every deployment.
        uint256 ts = block.timestamp;

        // Make the deciding call.  It may revert for parameter-level reasons
        // (e.g. the asset transfer fails or a prior pending decision exists),
        // so record that fact instead of letting it bubble up.
        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the resulting pending flash decision through the public mapping
        // getter.
        uint256 pendingAmount;
        uint256 pendingUnlockTime;
        address pendingAsset;
        bool pendingAssetBurnable;
        (pendingAmount, pendingUnlockTime, pendingAsset, pendingAssetBurnable) = c.pendingFlashDecision(target, sender);

        // General rule: whenever assertGovernanceApproved succeeds, the pending
        // decision for (target, sender) must equal the configured decision, with
        // the unlock time equal to the configuration's unlock time offset from
        // the timestamp of this call.  If the call reverted, no such guarantee
        // is claimed.
        if (!reverted) {
            assert(
                pendingAmount == configAmount &&
                pendingAsset == configAsset &&
                pendingAssetBurnable == configAssetBurnable &&
                pendingUnlockTime == ts + configUnlockTime
            );
        } else {
            assert(reverted);
        }
    }
}

