    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 unlockTime, address targetContract, address asset) public payable {
        require(amount > 0);
        require(unlockTime > 0);
        require(targetContract != address(0));
        require(asset != address(0));

        c.configureFlashGovernance(asset, amount, unlockTime, false);

        (uint256 beforeAmount, , , ) = c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterAmount, , , ) = c.pendingFlashDecision(targetContract, address(this));

        assert(reverted && afterAmount == beforeAmount);
    }

    receive() external payable {}
}

