contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address target, address caller, address asset) public {
        // First withdrawal attempt using the given caller.
        bool reverted1;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        // Read the decision after the first attempt.
        (uint256 amount1, uint256 unlockTime1, address asset1, bool burnable1) = c.pendingFlashDecision(target, caller);

        // Second identical withdrawal attempt.
        bool reverted2;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        // Read the decision after the second attempt.
        (uint256 amount2, uint256 unlockTime2, address asset2, bool burnable2) = c.pendingFlashDecision(target, caller);

        // The general rule: if the first withdrawal succeeded, it must have cleared the decision,
        // so the second identical withdrawal must revert and the stored amount must be zero.
        // Conversely, if the second withdrawal succeeded, the first must have succeeded too,
        // and the decision was cleared after the second.
        assert(
            (reverted1 || (!reverted2 && amount2 == 0)) &&
            (reverted2 || (!reverted1 && amount1 > 0 && amount2 == 0))
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address target, address caller, address asset) public payable {
        uint256 balBefore = address(this).balance;

        (uint256 amount, uint256 unlockTime, address assetStored, bool assetBurnable) = c.pendingFlashDecision(target, caller);
        require(assetStored == asset && amount > 0 && unlockTime < block.timestamp, "no eligible decision");

        bool reverted;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 amountAfter, uint256 unlockTimeAfter, address assetAfter, bool assetBurnableAfter) = c.pendingFlashDecision(target, caller);

        assert(
            !reverted &&
            amountAfter == 0 &&
            address(this).balance == balBefore + amount
        );
    }
}

