contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address targetContract,
        address user,
        bool emergency
    ) public payable {
        // Configure flash governance; onlySuccessfulProposal requires configured == false or
        // successfulProposal(msg.sender), so use DAO as msg.sender via c.setDAO.
        c.setDAO(address(this));
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Make the DAO an approved spender for the amount if we are dealing with a token.
        // The test contract itself must call approve on the asset; try/catch is not allowed here,
        // so only attempt if asset has code and behaves.
        if (asset.code.length > 0) {
            (bool okApproved, ) = asset.call(abi.encodeWithSignature("approve(address,uint256)", address(c), amount));
            require(okApproved, "approve failed");
        }

        bool reverted;
        try c.assertGovernanceApproved(user, targetContract, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            (uint256 gotAmount, uint256 gotUnlockTime, address gotAsset, bool gotAssetBurnable) =
                c.pendingFlashDecision(targetContract, user);
            assert(
                gotAmount == amount &&
                gotAsset == asset &&
                gotAssetBurnable == assetBurnable &&
                gotUnlockTime == block.timestamp + unlockTime
            );
        } else {
            assert(true);
        }
    }
}

