contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address[] calldata governables, bool[] calldata isGoverned, uint256 idx) public payable {
        require(governables.length == isGoverned.length);
        require(idx < governables.length);
        require(c.configured());
        require(_isSuccessfulProposal(msg.sender));

        c.setGoverned(governables, isGoverned);

        assert(c.governed(governables[idx]) == isGoverned[idx]);
    }

    function _isSuccessfulProposal(address sender) internal view returns (bool) {
        (bool success, bytes memory data) = c.DAO().staticcall(
            abi.encodeWithSignature("successfulProposal(address)", sender)
        );
        return success && data.length >= 32 && abi.decode(data, (bool));
    }

    receive() external payable {}
}

