contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address targetContract,
        address attacker,
        address asset,
        uint256 amount,
        uint256 unlockTime
    ) public {
        require(attacker != address(this), "attacker is test");
        require(asset != address(0), "asset zero");

        // A pending decision can only be created by a flash governance call from an
        // allowed sender (DAO or governed) with a valid ERC20 transferFrom.
        // Here we simply try to withdraw without any pending decision for the attacker.
        uint256 balBefore = address(this).balance;

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: withdrawing a governance asset when no pending flash decision
        // exists for msg.sender must revert. No state-changing preconditions are set,
        // so the pending mapping entry for (targetContract, this) is zero, failing the
        // require that checks amount > 0.
        assert(reverted);
        assert(address(this).balance == balBefore);
    }

    receive() external payable {}
}

