contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        address proposedAsset,
        uint256 proposedAmount,
        uint256 proposedUnlockTime,
        address target
    ) public {
        require(asset != address(0), "asset required");
        require(proposedAsset != address(0), "proposed asset required");
        require(target != address(0), "target required");
        require(amount > 0, "amount must be positive");
        require(proposedAmount > 0, "proposed amount must be positive");

        // make the caller (this test contract) a successful governance proposal actor
        c.setGoverned(new address[](0), new bool[](0));

        // configure the flash governance slot used for the sender's pending decision
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // --- simulate the public state another contract/user would read before and after ---

        // The pending record is stored keyed by (target, sender=msg.sender on assertGovernanceApproved,
        // but withdrawGovernanceAsset looks up (targetContract, msg.sender) where msg.sender is now this test).
        // The public mapping has two getters: pendingFlashDecision(address,address).
        // After assertGovernanceApproved fails/reverts or succeeds, we can inspect what was recorded.

        // Call the governance approval on c itself as the target, so the pending record key is (c, c).
        // The asset transferFrom may fail for a non-token, so we capture reverts and instead focus on
        // the state observable through the withdrawal path.

        // Prepare: authorise this test contract as sender by calling assertGovernanceApproved
        // with c as the sender and target.
        // If the asset call reverts, no pending record is created, and withdraw must also revert.

        (bool created, ) = address(c).call(
            abi.encodeWithSignature(
                "assertGovernanceApproved(address,address,bool)",
                address(c),
                target,
                true
            )
        );

        // Configure again with different values, so we know whether the pending record matches
        if (created) {
            c.configureFlashGovernance(proposedAsset, proposedAmount, proposedUnlockTime, false);
        }

        // Re-read the pending decision key for (target, this) after the possible change
        (uint256 pendAmountBefore, uint256 pendUnlockBefore, address pendAssetBefore, bool pendBurnableBefore) =
            c.pendingFlashDecision(target, address(this));

        // sanity: keep variables referenced so the compiler is happy
        require(pendAmountBefore <= type(uint256).max, "unused");
        require(pendUnlockBefore <= type(uint256).max, "unused");
        require(pendAssetBefore != proposedAsset || pendAssetBefore == proposedAsset, "unused");
        require(pendBurnableBefore == pendBurnableBefore, "unused");

        // The contract's enforceTolerance is a pure view over its security parameters;
        // query security parameters that govern the flash decision timing.
        (uint256 secEpochSize, uint256 secLastAct, uint8 secMaxGovernanceChangePerEpoch, uint8 secChangeTolerance) =
            c.security();
        require(secEpochSize <= type(uint256).max, "unused");
        require(secLastAct <= type(uint256).max, "unused");
        require(secMaxGovernanceChangePerEpoch == secMaxGovernanceChangePerEpoch, "unused");
        require(secChangeTolerance == secChangeTolerance, "unused");

        // The general rule we prove: for every input, withdrawing a pending decision
        // for (target, caller) either reverts when no valid pending record exists,
        // or it transfers exactly the recorded amount and deletes the record.
        //
        // We observe the outcome: call withdrawGovernanceAsset and record whether it reverted,
        // plus read the balance of this test contract before and after (for the configured asset).

        // Read the recorded expected amount/dAsset before withdrawing.
        (uint256 expectedAmount, uint256 expectedUnlock, address expectedAsset, bool expectedBurnable) =
            c.pendingFlashDecision(target, address(this));

        bool hasPending = expectedAmount > 0 && expectedAsset != address(0) && expectedUnlock < block.timestamp;

        bool reverted;
        try c.withdrawGovernanceAsset(target, expectedAsset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (hasPending) {
            // Rule: if the pending record was valid and withdrawable, the call must not revert,
            // and the pending record must now be deleted (zeroed).
            assert(!reverted);
            (uint256 afterAmount, uint256 afterUnlock, address afterAsset, bool afterBurnable) =
                c.pendingFlashDecision(target, address(this));
            assert(afterAmount == 0 && afterUnlock == 0 && afterAsset == address(0) && !afterBurnable);
        } else {
            // Rule: if there is no valid pending record, the call must revert.
            assert(reverted);
        }
    }

    receive() external payable {}
}

