contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, address sender) public {
        // Read the stored flash-governance config (public getter) before the deciding call.
        (uint256 amountBefore, uint256 unlockBefore, address assetBefore, bool burnableBefore) = c.flashGovernanceConfig();

        // Read the pending decision for (target, sender) before the deciding call.
        (uint256 pAmountBefore, uint256 pUnlockBefore, address pAssetBefore, bool pBurnableBefore) = c.pendingFlashDecision(target, sender);

        // Precondition that would make the deciding call pass the guard: there must be
        // enough balance for sender to transfer `amountBefore` tokens and the pending
        // decision must have unlockTime <= block.timestamp (i.e. no earlier time logic).
        // Since this test cannot mint tokens or set token balances, we choose inputs that
        // do NOT satisfy the balance requirement so the branch reverts. We use target and
        // sender as parameters so the proof is over all (target, sender).
        uint256 balBefore;
        if (assetBefore != address(0)) {
            // read token balance of sender through the public ERC20 surface
            balBefore = IERC20(assetBefore).balanceOf(sender);
        } else {
            balBefore = 0;
        }

        // Choose the deciding call: assertGovernanceApproved with emergency = false.
        // It must revert because the guard (transferFrom success AND unlockTime <= now)
        // cannot pass when balance < amount; this is the general rejection rule.
        // If it does not revert, the else-branch is entered and the whole update happens.
        bool reverted;
        try c.assertGovernanceApproved(sender, target, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, read the storage again to observe any mutation.
        (uint256 pAmountAfter, uint256 pUnlockAfter, address pAssetAfter, bool pBurnableAfter) = c.pendingFlashDecision(target, sender);

        // General rule: whenever the flash decision was rejected (reverted), the stored
        // pendingFlashDecision entry for (target, sender) must be completely unchanged.
        // The `|| !reverted` makes the assertion true for the (possibly accepted) other
        // branch, but for the revert branch it pins down that no state was written.
        assert(
            !reverted ||
            (pAmountAfter == pAmountBefore &&
             pUnlockAfter == pUnlockBefore &&
             pAssetAfter == pAssetBefore &&
             pBurnableAfter == pBurnableBefore)
        );
    }

    receive() external payable {}
}

