        c = _c;
    }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        address targetContract,
        address caller
    ) public {
        // Setup: configure the flash governance config (this is a no-op unless
        // sender is a successful proposal, but it establishes the intended config).
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        uint256 cBalBefore = IERC20(asset).balanceOf(address(c));
        uint256 callerBalBefore = IERC20(asset).balanceOf(caller);

        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "withdrawGovernanceAsset(address,address)",
                targetContract,
                caller
            )
        );

        // Read the updated state through the public getter.
        (uint256 amt, uint256 unlock, address a, bool burnable) =
            c.pendingFlashDecision(targetContract, caller);

        uint256 cBalAfter = IERC20(asset).balanceOf(address(c));
        uint256 callerBalAfter = IERC20(asset).balanceOf(caller);

        // General rule: a successful withdrawal must consume the pending record
        // (amount becomes 0) and move exactly the pending amount from c to caller.
        if (ok) {
            assert(
                amt == 0 &&
                callerBalAfter == callerBalBefore + amount &&
                cBalAfter == cBalBefore - amount
            );
        } else {
            // On revert, the pending record must be unchanged or freshly zero.
            assert(amt == amount || amt == 0);
        }
    }
}

