contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address targetContract,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable
    ) public {
        require(asset != address(0), "bad asset");
        require(amount > 0, "bad amount");

        // Configure flash governance so that assertGovernanceApproved and
        // pendingFlashDecision get populated with the parameters we want to test.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Record the state before the deciding call.
        uint256 beforeAmount = c.balanceOf(address(c));

        // Make the pending decision for (targetContract, this) actually exist and mature.
        // We only enter withdrawGovernanceAsset if the stored unlockTime is in the past,
        // so pass a decision with zero remaining lock-time by using the contract's
        // own configured unlockTime already being 0 or by ensuring the stored
        // unlockTime is exactly 0 relative to block.timestamp.  Because
        // configureFlashGovernance sets the raw config, and assertGovernanceApproved
        // adds block.timestamp to unlockTime, we first obtain a fresh pending
        // decision, then immediately test withdrawal with the smallest possible
        // maturity.  To avoid relying on time travel, we only exercise the
        // “matured” branch using a decision whose total stored unlockTime is 0
        // (which happens whenever the configured flashGovernanceConfig.unlockTime
        // is 0 and the contract's clock does not advance between the two calls).
        // We cannot guarantee clock behavior, but we can assert the general
        // invariant of the withdraw function's effect on stale pending data.

        // Instead of relying on timing, populate the pending decision directly by
        // invoking the governance-approved path with parameters that make the
        // stored unlockTime already expired.
        c.assertGovernanceApproved(address(this), targetContract, true);

        // Read the stored pending decision that assertGovernanceApproved wrote.
        (uint256 storedAmount, uint256 storedUnlock, address storedAsset, bool storedBurnable) =
            c.pendingFlashDecision(targetContract, address(this));

        // Precondition: the stored decision must be withdrawable, i.e. it must
        // reference a nonzero amount and already be unlocked.
        require(storedAmount > 0, "no pending decision");
        require(storedUnlock < block.timestamp, "still locked");
        require(storedAsset == asset, "asset mismatch");

        // The actual deciding call.  It is a top-level statement because it
        // changes c's state.
        c.withdrawGovernanceAsset(targetContract, asset);

        // Read the state after the deciding call.
        (uint256 afterAmount, uint256 afterUnlock, address afterAsset, bool afterBurnable) =
            c.pendingFlashDecision(targetContract, address(this));

        // General rule: after withdrawGovernanceAsset succeeds for a matured
        // pending decision, that decision is fully cleared: the stored amount,
        // unlock time, asset and burnable flag are all reset to their zero values,
        // and the contract's balance of the underlying token decreases by the
        // withdrawn amount (or at least does not increase incorrectly).
        assert(
            afterAmount == 0 &&
            afterUnlock == 0 &&
            afterAsset == address(0) &&
            !afterBurnable
        );
    }
}

