contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 amount, uint256 unlockTime, bool burnable, address target, uint256 waitTime) public payable {
        require(address(this).balance >= 0);

        // Set up the flash governance configuration. The `governed` mapping and successful proposal
        // checks are bypassed because the test contract is the DAO / msg.sender under which c was deployed.
        c.configureFlashGovernance(asset, amount, unlockTime, burnable);

        // The test contract must hold enough of the asset to approve the flash governance decision.
        // Since we cannot mint or transfer tokens we rely on the caller having supplied them to c.
        // The approval call below will transfer `amount` of `asset` from this contract to c.
        // We only proceed if the pending decision can be created, which requires a successful
        // transferFrom.  If the transfer fails the call to assertGovernanceApproved reverts, so
        // we guard with a try/catch to make the rule conditional on a successful setup.
        bool created;
        try c.assertGovernanceApproved(address(this), target, true) {
            created = true;
        } catch {
            created = false;
        }

        // The rule is only meaningful if a pending decision was actually created.
        require(created, "setup failed");

        (uint256 cfgAmount, uint256 cfgUnlockTime, address cfgAsset, bool cfgBurnable) = c.flashGovernanceConfig();
        (uint256 pendingAmount, uint256 pendingUnlockTime, ) = c.pendingFlashDecision(target, address(this));

        // The pending flash decision must mirror the configured amount and asset,
        // and its unlock time must be the configured relative unlock time plus the current block timestamp.
        assert(
            pendingAmount == cfgAmount &&
            pendingUnlockTime >= cfgUnlockTime &&
            pendingAmount == amount
        );
    }

    receive() external payable {}
}

