contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address targetContract, address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public {
        require(unlockTime <= 1000000000000);

        // read initial pending state through the public getter
        (uint256 pendingAmountBefore, uint256 pendingUnlockBefore, address pendingAssetBefore, bool pendingBurnableBefore) = c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 pendingAmountAfter, uint256 pendingUnlockAfter, address pendingAssetAfter, bool pendingBurnableAfter) = c.pendingFlashDecision(targetContract, address(this));

        // The withdraw call must succeed iff the pre-state entry existed with a non-zero amount,
        // the requested asset matched, and it was already unlocked.  On success the pending entry
        // must be deleted (amount becomes zero), and on revert the pre-state must not have been
        // zeroed (amount is unchanged).
        bool eligible = pendingAmountBefore > 0 && pendingAssetBefore == asset && pendingUnlockBefore < block.timestamp;

        if (!eligible) {
            assert(reverted);
        } else {
            assert(!reverted);
        }

        // If the call was ineligible it must have reverted and left the pending amount intact.
        // If it was eligible it must have succeeded and zeroed the pending amount.
        assert(reverted ? pendingAmountAfter == pendingAmountBefore : pendingAmountAfter == 0);
    }

    receive() external payable {}
}

