contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, address user, address asset, uint256 amount) public {
        // burnFlashGovernanceAsset requires the caller to be a successful proposal.
        // Since this test contract is the deployer of c, on a fresh c, c.DAO()
        // is the address supplied at deployment, not address(this). To make the
        // "successful proposal" check pass via the `!configured` branch, we must
        // ensure c is not configured: configured is false by default on a fresh c.
        // However, `assertSuccessfulProposal` checks
        //   require(!configured || LimboDAOLike(DAO).successfulProposal(sender), "EJ");
        // With configured == false, the require passes for any sender.
        // We must avoid calling endConfiguration, and avoid any setter that
        // would set configured true. Only a successful proposal call may set it,
        // and we do not have that.

        // Read before-state through the public getter pendingFlashDecision.
        (uint256 beforeAmount, uint256 beforeUnlock, address beforeAsset, bool beforeBurnable) =
            c.pendingFlashDecision(target, user);

        // Record the contract's balances before the call to reason about token moves.
        uint256 cAssetBalanceBefore = IERC20(asset).balanceOf(address(c));
        address userAddr = user;
        uint256 userAssetBalanceBefore = IERC20(asset).balanceOf(userAddr);

        // The deciding call: clears the pending decision entry.
        bool reverted;
        try c.burnFlashGovernanceAsset(target, user, asset, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state.
        (uint256 afterAmount, uint256 afterUnlock, address afterAsset, bool afterBurnable) =
            c.pendingFlashDecision(target, user);

        // General rule: a successful call (that does not revert) leaves the
        // pendingFlashDecision entry for (target,user) completely cleared:
        // asset == address(0), amount == 0, unlockTime == 0, assetBurnable == false.
        // If the entry was already empty before, it remains empty.
        // Additionally, if reverted is false, the asset burn path is only taken
        // when beforeBurnable was true, and then the burn amount is bounded by
        // the amount argument; we assert the cleared state invariant.
        assert(reverted || (afterAsset == address(0) && afterAmount == 0 && afterUnlock == 0 && !afterBurnable));
    }

    receive() external payable {}
}

