contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address target,
        address user,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable
    ) public payable {
        require(asset != address(0), "asset zero");

        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        (uint256 amountStored, uint256 unlockTimeStored, address assetStored, bool burnableStored) = c.flashGovernanceConfig();

        bool hasPending;
        address pendingAsset;
        uint256 pendingUnlockTime;
        uint256 pendingAmount;
        bool pendingBurnable;
        if (assetStored != address(0)) {
            (pendingAmount, pendingUnlockTime, pendingAsset, pendingBurnable) =
                c.pendingFlashDecision(target, user);
            hasPending = pendingAsset != address(0) || pendingAmount > 0;
        }

        require(assetStored == asset && amountStored == amount && unlockTimeStored == unlockTime && burnableStored == assetBurnable, "config mismatch");

        uint256 balBefore = address(c).balance;
        c.burnFlashGovernanceAsset(target, user, asset, amount);
        uint256 balAfter = address(c).balance;

        if (hasPending) {
            (uint256 pendingAmountAfter, uint256 pendingUnlockTimeAfter, address pendingAssetAfter, bool pendingBurnableAfter) =
                c.pendingFlashDecision(target, user);
            assert(
                !assetBurnable
                    ? (pendingAssetAfter == address(0) && pendingAmountAfter == 0)
                    : true
            );
        }

        assert(balAfter <= balBefore && assetStored == asset && amountStored == amount && unlockTimeStored == unlockTime && burnableStored == assetBurnable);
    }

    receive() external payable {}
}
